function numericField(obj,key){const n=Number(obj?.[key]);return Number.isFinite(n)?Math.max(0,Math.min(5,n)):0}
function actorPowerScore(actor){const raw=numericField(actor,'financial')+numericField(actor,'decision_access')+numericField(actor,'disruption_capacity')+numericField(actor,'media_influence');return Math.round(Math.min(20,raw))}
function narrativeStrengthScore(n){return Math.round(Math.min(15,numericField(n,'coherence')+numericField(n,'media_alignment')+numericField(n,'public_acceptance')))}
function toolPressureScore(tool){const cost=numericField(tool,'cost'),risk=numericField(tool,'risk'),speed=numericField(tool,'speed'),rev=numericField(tool,'reversibility'),den=numericField(tool,'deniability');return Math.round(Math.min(100,((cost+risk+speed+(6-rev)+den)/25)*100))}
function interestWeightScore(x){const intensity=numericField(x,'intensity');const stake={marginal:1,important:1.3,existential:1.65}[normalizeToken(x?.stakes)]||1;const horizon={short:1,medium:1.15,long:1.25}[normalizeToken(x?.horizon)]||1;return Math.round(Math.min(100,(intensity/5)*100*stake*horizon/2.06))}
function modelMetricLabel(kind){return ({api:'API',nsi:'NSI',tps:'TPS',iw:'IW'})[kind]||kind}
function modelMetricCard(label,value,max,sub,cls='pct-neutral'){const pct=max?Math.round((value/max)*100):value;return `<div class="modelMetric ${cls}"><span>${escapeHtml(label)}</span><b>${escapeHtml(value)}${max?`/${max}`:''}</b><small>${escapeHtml(sub)}</small></div>`}
