function schemaHealth(a=state.analysis){if(!a)return {pct:0,missing:[],next:t('healthMissingPillars')};const missing=[];const pillarFilled=PILLARS.filter(p=>normalizeArray(a[p]).length>0).length;if(pillarFilled<6)missing.push(t('healthMissingPillars'));if(!normalizeArray(a.contradictions?.items).length)missing.push(t('healthMissingContradictions'));const sc=normalizeArray(a.scenarios?.items);if(!sc.length)missing.push(t('healthMissingScenarios'));if(sc.some(s=>!normalizeArray(s.disproven_if).length))missing.push(t('healthMissingScenarios'));if(!normalizeArray(a.feedback).length)missing.push(t('healthMissingFeedback'));const ev=normalizeArray(a.evidence?.items),ass=normalizeArray(a.assumptions?.items);if(!ev.length&&!ass.length)missing.push(t('healthMissingEvidence'));if(ev.length&&!ev.some(e=>/source/.test(normalizeToken(e.basis))))missing.push(labelText('Add at least one source-grounded evidence item.','Ø£Ø¶Ù Ø¯Ù„ÙŠÙ„Ù‹Ø§ ÙˆØ§Ø­Ø¯Ù‹Ø§ Ø¹Ù„Ù‰ Ø§Ù„Ø£Ù‚Ù„ Ù…Ø±ØªÙƒØ²Ù‹Ø§ Ø¹Ù„Ù‰ Ù…ØµØ¯Ø±.'));if(ev.length&&!ev.some(e=>(e.counter_evidence||e.counterEvidence||'').trim()))missing.push(labelText('Add counter-evidence or uncertainty pressure.','Ø£Ø¶Ù Ø¯Ù„ÙŠÙ„Ù‹Ø§ Ù…Ø¶Ø§Ø¯Ù‹Ø§ Ø£Ùˆ Ø¶ØºØ· Ø¹Ø¯Ù… ÙŠÙ‚ÙŠÙ†.'));const checks=13;let passed=0;passed+=pillarFilled;passed+=normalizeArray(a.contradictions?.items).length?1:0;passed+=sc.length?1:0;passed+=sc.length&&sc.every(s=>normalizeArray(s.disproven_if).length)?1:0;passed+=(ev.length||ass.length)?1:0;passed+=ev.some(e=>/source/.test(normalizeToken(e.basis)))?1:0;passed+=ev.some(e=>(e.counter_evidence||e.counterEvidence||'').trim())?1:0;passed+=a.schema_version?1:0;const pct=Math.round(Math.min(100,(passed/checks)*100));return {pct,missing:[...new Set(missing)],next:missing[0]||t('healthGood')}}
