function getWarnings(){if(!state.analysis)return [t('emptyEngine')];const a=state.analysis;const w=[];const ev=normalizeArray(a.evidence?.items);if(PILLARS.some(p=>!a[p].length))w.push(t('warnings.missingPillars'));if(!a.contradictions.items.length)w.push(t('warnings.noContradictions'));if(!a.scenarios.items.length)w.push(t('warnings.noScenarios'));if(a.scenarios.items.length&&a.scenarios.items.some(s=>!normalizeArray(s.disproven_if).length))w.push(t('warnings.noFalsifiers'));if((!a.evidence||!ev.length)&&(!a.assumptions||!normalizeArray(a.assumptions.items).length))w.push(t('warnings.thinEvidence'));if(ev.length&&!ev.some(e=>/source/.test(normalizeToken(e.basis))))w.push(labelText('Evidence exists, but no source-grounded item is marked.','ØªÙˆØ¬Ø¯ Ø£Ø¯Ù„Ø©ØŒ Ù„ÙƒÙ† Ù„Ø§ ÙŠÙˆØ¬Ø¯ Ø¹Ù†ØµØ± Ù…Ø±ØªÙƒØ² Ø¹Ù„Ù‰ Ù…ØµØ¯Ø±.'));if(ev.length&&!ev.some(e=>(e.counter_evidence||e.counterEvidence||'').trim()))w.push(labelText('Counter-evidence is missing. Add pressure against the thesis.','Ø§Ù„Ø¯Ù„ÙŠÙ„ Ø§Ù„Ù…Ø¶Ø§Ø¯ ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯. Ø£Ø¶Ù Ø¶ØºØ·Ù‹Ø§ Ø¶Ø¯ Ø§Ù„Ø£Ø·Ø±ÙˆØ­Ø©.'));if(!w.length)w.push(t('warnings.good'));return w;}
