function basisInfo(v){const s=normalizeToken(v);if(/source/.test(s))return {label:labelText('Source-grounded','Ù…Ø±ØªÙƒØ² Ø¹Ù„Ù‰ Ù…ØµØ¯Ø±'),cls:'basis-source'};if(/observation|observed|Ù…Ù„Ø§Ø­Ø¸Ø©/.test(s))return {label:labelText('Direct observation','Ù…Ù„Ø§Ø­Ø¸Ø© Ù…Ø¨Ø§Ø´Ø±Ø©'),cls:'basis-observed'};if(/inference|inferred|Ø§Ø³ØªÙ†ØªØ§Ø¬/.test(s))return {label:labelText('Analytical inference','Ø§Ø³ØªÙ†ØªØ§Ø¬ ØªØ­Ù„ÙŠÙ„ÙŠ'),cls:'basis-inferred'};if(/estimate|estimated|ØªÙ‚Ø¯ÙŠØ±/.test(s))return {label:labelText('Estimate','ØªÙ‚Ø¯ÙŠØ±'),cls:'basis-estimate'};if(/assumption|assumed|Ø§ÙØªØ±Ø§Ø¶/.test(s))return {label:labelText('Working assumption','Ø§ÙØªØ±Ø§Ø¶ Ø¹Ù…Ù„ÙŠ'),cls:'basis-assumption'};return {label:displayEnum(v),cls:'basis-neutral'}}
