function riskInfo(v){const score=riskScore(v);let label=labelText('Risk not specified','Ø§Ù„Ù…Ø®Ø§Ø·Ø± ØºÙŠØ± Ù…Ø­Ø¯Ø¯Ø©');const s=normalizeToken(v);if(/critical|existential|severe|Ø­Ø§Ø³Ù…|ÙˆØ¬ÙˆØ¯|Ø®Ø·ÙŠØ±/.test(s))label=labelText('Critical risk','Ù…Ø®Ø§Ø·Ø± Ø­Ø±Ø¬Ø©');else if(/high|major|Ù…Ø±ØªÙØ¹|Ø¹Ø§Ù„/.test(s))label=labelText('High risk','Ù…Ø®Ø§Ø·Ø± Ø¹Ø§Ù„ÙŠØ©');else if(/medium|moderate|material|important|Ù…ØªÙˆØ³Ø·|Ù…Ù‡Ù…/.test(s))label=labelText('Medium risk','Ù…Ø®Ø§Ø·Ø± Ù…ØªÙˆØ³Ø·Ø©');else if(/low|minor|contained|Ù…Ù†Ø®ÙØ¶|Ù…Ø­Ø¯ÙˆØ¯/.test(s))label=labelText('Low risk','Ù…Ø®Ø§Ø·Ø± Ù…Ù†Ø®ÙØ¶Ø©');return {label,cls:pctClass(score),score}}
