  source_based:[labelText('Source-grounded','Ù…Ø±ØªÙƒØ² Ø¹Ù„Ù‰ Ù…ØµØ¯Ø±'),'basis-source'],source_grounded:[labelText('Source-grounded','Ù…Ø±ØªÙƒØ² Ø¹Ù„Ù‰ Ù…ØµØ¯Ø±'),'basis-source'],observation:[labelText('Direct observation','Ù…Ù„Ø§Ø­Ø¸Ø© Ù…Ø¨Ø§Ø´Ø±Ø©'),'basis-observed'],inference:[labelText('Analytical inference','Ø§Ø³ØªÙ†ØªØ§Ø¬ ØªØ­Ù„ÙŠÙ„ÙŠ'),'basis-inferred'],estimate:[labelText('Estimate','ØªÙ‚Ø¯ÙŠØ±'),'basis-estimate'],assumption:[labelText('Working assumption','Ø§ÙØªØ±Ø§Ø¶ Ø¹Ù…Ù„ÙŠ'),'basis-assumption']
