  const s=[c.contradiction_type,c.type,c.rhetoric,c.interpretation,arr(c.actions).join(' ')].join(' ').toLowerCase();const hits=[];
  if(/interest|material|economic|alliance|sovereign|Ù…ØµÙ„Ø­Ø©/.test(s))hits.push('interests');
  if(/actor|party|state|union|coalition|ÙØ§Ø¹Ù„/.test(s))hits.push('actors');
  if(/tool|sanction|policy|military|instrument|Ø£Ø¯Ø§Ø©/.test(s))hits.push('tools');
