function scoreBreakdown(a=state.analysis){if(!a)return {completeness:0,coherence:0,contradictions:0,falsifiability:0,evidence:0,readiness:0,overall:0};const filled=PILLARS.filter(p=>normalizeArray(a[p]).length).length;const completeness=Math.round((filled/6)*100);const hasCore=normalizeArray(a.interests).length&&normalizeArray(a.actors).length&&normalizeArray(a.tools).length&&normalizeArray(a.results).length;const feedback=normalizeArray(a.feedback).length;const actorDims=normalizeArray(a.actors).length?normalizeArray(a.actors).filter(x=>actorPowerScore(x)>0).length/normalizeArray(a.actors).length:0;const nsiDims=normalizeArray(a.narrative).length?normalizeArray(a.narrative).filter(x=>narrativeStrengthScore(x)>0).length/normalizeArray(a.narrative).length:0;const coherence=Math.min(100,Math.round((filled/6)*42+(hasCore?24:0)+(feedback?18:0)+(actorDims+nsiDims)*8));const con=normalizeArray(a.contradictions?.items);const contradictions=Math.min(100,con.length*16+con.filter(c=>arr(c.actions).length>=2).length*8+con.filter(c=>(c.interpretation||'').trim()).length*7+con.filter(c=>affectedLayers(c).length).length*5);const sc=normalizeArray(a.scenarios?.items);const falsifiability=sc.length?Math.min(100,sc.length*14+Math.round((sc.filter(s=>arr(s.disproven_if).length).length/sc.length)*50)+sc.filter(s=>s.probability!==undefined&&s.probability!==null&&s.probability!=='').length*8):0;const ev=normalizeArray(a.evidence?.items),ass=normalizeArray(a.assumptions?.items);const sourceShare=ev.length?Math.round((ev.filter(e=>/source/.test(normalizeToken(e.basis))).length/ev.length)*34):0;const counterShare=ev.length?Math.round((ev.filter(e=>(e.counter_evidence||e.counterEvidence||'').trim()).length/ev.length)*18):0;const evidence=Math.min(100,ev.length*9+ass.length*7+sourceShare+counterShare);const warnings=getWarnings(a).filter(w=>w!==t('warnings.good')).length;const readiness=Math.max(0,Math.min(100,70+completeness*.16+contradictions*.10+evidence*.14-warnings*12));const overall=Math.round(completeness*.25+coherence*.20+contradictions*.15+falsifiability*.15+evidence*.15+readiness*.10);return {completeness,coherence,contradictions,falsifiability,evidence,readiness,overall}}
