function scoreFormulaText(){return labelText('Overall score = 25% completeness + 20% coherence + 15% contradiction quality + 15% scenario testability + 15% evidence grounding + 10% share readiness.','Ø§Ù„Ù…Ø¤Ø´Ø± Ø§Ù„ÙƒÙ„ÙŠ = 25% Ø§ÙƒØªÙ…Ø§Ù„ Ø§Ù„Ø·Ø¨Ù‚Ø§Øª + 20% Ø§Ù„ØªÙ…Ø§Ø³Ùƒ Ø§Ù„Ø³Ø¨Ø¨ÙŠ + 15% Ø¬ÙˆØ¯Ø© Ø§Ù„ØªÙ†Ø§Ù‚Ø¶Ø§Øª + 15% Ù‚Ø§Ø¨Ù„ÙŠØ© Ø§Ø®ØªØ¨Ø§Ø± Ø§Ù„Ø³ÙŠÙ†Ø§Ø±ÙŠÙˆÙ‡Ø§Øª + 15% Ø§Ø±ØªÙƒØ§Ø² Ø§Ù„Ø£Ø¯Ù„Ø© + 10% Ø¬Ø§Ù‡Ø²ÙŠØ© Ø§Ù„Ù…Ø´Ø§Ø±ÙƒØ©.')}
function scoreFormulaHtml(){const weights=scoreWeights();const entries=Object.keys(weights).map(k=>`<div class="formulaWeight"><span>${escapeHtml(scoreWeightLabel(k))}</span><b>${weights[k]}%</b></div>`).join('');const bands=[['pct-low','0â€“34'],['pct-warn','35â€“55'],['pct-mid','56â€“75'],['pct-good','76â€“89'],['pct-excellent','90â€“100']].map(([cls,label])=>`<span class="bandChip ${cls}"><span class="bandDot"></span>${label}</span>`).join('');return `<div class="scoreFormulaCard"><h4>${escapeHtml(labelText('Scoring formula','Ù…Ø¹Ø§Ø¯Ù„Ø© Ø§Ù„ØªÙ‚ÙŠÙŠÙ…'))}</h4><p>${escapeHtml(scoreFormulaText())}</p><div class="formulaGrid">${entries}</div><div class="scoreBandLegend" aria-label="${escapeHtml(labelText('Score bands','Ù…Ø³ØªÙˆÙŠØ§Øª Ø§Ù„Ø¯Ø±Ø¬Ø©'))}">${bands}</div></div>`}
